int minimumTourLength(int N, int[] X) {
    int totalLength = 0;
    for (int i = 0; i < N; i++) {
        totalLength += Math.abs(X[i] - X[(i + 1) % N]);
    }

    int minTourLength = Integer.MAX_VALUE;
    for (int i = 0; i < N; i++) {
        int currentLength = totalLength - Math.abs(X[i] - X[(i + 1) % N]) - Math.abs(X[(i + 1) % N] - X[(i + 2) % N]) + Math.abs(X[i] - X[(i + 2) % N]);
        minTourLength = Math.min(minTourLength, currentLength);
    }

    return minTourLength;
}
